public class TarUtils_parseOctal_TriageGen0Test {







    @Test
    public void testParseOctal_ZeroBufferStart() {
        // The code has a specific optimization: if (buffer[start] == 0) return 0L;
        // Note: buffer[start] refers to the byte value 0 (NUL), not the character '0'
        byte[] buffer = new byte[10];
        buffer[0] = 0; 
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 5));
    }














