package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen0Test {





















    /**
     * Note: The logic for trimming trailing NULs in the provided source code 
     * contains: while (start < end && (trailer == 0 || false))
     * Since (trailer == 0 || false) is equivalent to (trailer == 0), 
     * and 'trailer' is initialized to buffer[end-1], 
     * if the last byte is 0, it enters the loop.
     */
    @Test
    public void testParseOctal_TrailingNUL() {
        byte[] buffer = new byte[]{'0', '7', 0};
        // offset 0, length 3. buffer[2] is 0.
        // The loop 'while (start < end && (trailer == 0 || false))' 
        // will decrement end.
        assertEquals(7L, TarUtils.parseOctal(buffer, 0, 3));
    }
}
